const msg = $('Normalizar mensaje').first().json;
const res = $input.first().json || {};
const filas = Array.isArray(res.data) ? res.data : [];
const digitos = (s) => String(s || '').replace(/\D/g, '');
const tel = digitos(msg.telefono);

// Busca al lead por telefono (puede venir de la llamada de voz)
const coincidencias = tel ? filas.filter((r) => digitos(r.telefono) === tel) : [];
const lead = coincidencias.length ? coincidencias[coincidencias.length - 1] : null;
const leadId = lead && lead.id ? String(lead.id) : 'TEL-' + tel;

const etiquetas = [
  ['nombre', 'Nombre'], ['empresa', 'Empresa'], ['sector', 'Sector'], ['tamano', 'Tamaño'],
  ['problema', 'Problema'], ['procesos_manuales', 'Procesos manuales'],
  ['quiere_automatizar', 'Quiere automatizar'], ['interes', 'Interés'], ['urgencia', 'Urgencia'],
  ['decisor', 'Decisor'], ['estado', 'Estado'], ['cita_id', 'Cita ya agendada (ID)'],
  ['proximo_paso', 'Próximo paso'], ['notas', 'Notas'], ['canal', 'Canal de origen']
];

let contexto = 'Es un contacto nuevo; aún no sabemos nada de él.';
if (lead) {
  const lineas = etiquetas
    .filter(([k]) => lead[k] !== undefined && String(lead[k]).trim() !== '')
    .map(([k, et]) => '- ' + et + ': ' + lead[k]);
  contexto = lineas.length ? lineas.join('\n') : 'Contacto ya registrado pero sin datos.';
}
const nombreWa = msg.nombre_perfil
  ? 'Nombre en su perfil de WhatsApp: ' + msg.nombre_perfil + ' (puede no ser el real)'
  : '';
const texto = String(msg.texto || '').trim() || '[Mensaje de audio que no se pudo transcribir]';

// Si es una foto, adjunta la imagen descargada para que el agente la vea
let binary;
if (msg.tipo === 'image') {
  try { binary = $('Descargar imagen').first().binary; } catch (e) { binary = undefined; }
}

const salida = {
  json: {
    texto: texto,
    telefono: msg.telefono,
    lead_id: leadId,
    es_nuevo: !lead,
    contexto_lead: [contexto, nombreWa].filter(Boolean).join('\n')
  }
};
if (binary) salida.binary = binary;
return [salida];

