const row = { id: c.lead_id, telefono: c.telefono };
if (c.es_nuevo) { row.creado = new Date().toISOString(); row.canal = 'whatsapp'; row.estado = 'contactado'; }
Object.entries(campos).forEach(([k, v]) => { if (v !== '' && v !== null && v !== undefined) row[k] = v; });
return JSON.stringify({ secret: $('Config').first().json.secret, action: 'sheets.appendOrUpdate', sheet: 'Leads', row: row, matchingColumns: ['id'] });
})() }}

