// Convierte lo que escribes en el chat en un mensaje con la misma forma que el webhook de YCloud
const entrada = String($input.first().json.chatInput || '').trim();
const m = entrada.match(/^reaccion:\s*(.+)$/i);
const wa = {
  from: '+34600000000',
  to: '+34900000000',
  customerProfile: { name: 'Prueba chat' }
};
if (m) {
  wa.type = 'reaction';
  wa.reaction = { emoji: m[1] };
} else {
  wa.type = 'text';
  wa.text = { body: entrada };
}
return [{ json: { body: { type: 'whatsapp.inbound_message.received', whatsappInboundMessage: wa } } }];

